paths=probe["paths"]
def sha(data): return hashlib.sha256(data).hexdigest()
result={}
for key,p in paths.items():
 if not os.path.lexists(p): result[key]={'present':False};continue
 st=os.lstat(p)
 if key=='ready':
  assert stat.S_ISDIR(st.st_mode)
  result[key]={'present':True,'directory':True,'entries':os.listdir(p)}
 else:
  assert stat.S_ISREG(st.st_mode) and st.st_size<=262144
  data=open(p,'rb').read()
  result[key]={'present':True,'bytes':len(data),'sha256':sha(data),'base64':base64.b64encode(data)}
expected={'claim': {'base64': 'eyJwaGFzZSI6ICJjbGFpbSIsICJ3YWxsX3RpbWUiOiAxMzg4NjI0NjUyLjMzNTE3NjksICJ1cHRpbWUiOiAiMjMuOTAgMTQuMzIiLCAiYm9vdF9pZCI6ICIwN2M1ZmM5OS02ZjRkLTRlZTItOTE3Yy04MjkyMWQyOGQwN2IifQ==', 'sha256': '96f22b7d4509f3e7c96e52eac1d0b05f7d4501cadadd66667250ae4adf71fc9c', 'bytes': 127, 'present': True}, 'tsk2': {'present': False}, 'tsk1': {'present': False}, 'mem': {'present': False}, 'worker': {'base64': '', 'sha256': '0eaf6dfb449af0a41f7a2b2ce267a409075fc682f66169ce6cdcc6ce22b04846', 'bytes': 2007, 'present': True}, 'va2': {'present': False}, 'done': {'present': False}, 'autoexec': {'base64': '', 'sha256': '2b085301d67bb374ffa18b9247eb58e835fa7be07091f2be0e87c5ff00a11bc6', 'bytes': 1296, 'present': True}, 'fingerprint': {'base64': 'AwCg4R7/L+E=', 'sha256': '5e64b91b57eaf124341a5f84484d853cfe5e97bae40e8d7c8bf60c7ed4c6969d', 'bytes': 8, 'present': True}, 'ready': {'directory': True, 'present': True, 'entries': []}, 'pool2': {'present': False}, 'pool1': {'present': False}, 'va1': {'present': False}}
assert result==expected, 'Target files changed since collection'
for key in ('autoexec','worker'):
 if result[key]['present']:
  assert result[key]['sha256']==probe['payload_sha256'][key]
if result['ready']['present']: assert result['ready']['entries']==[]
# All files verified before deleting any; uncollected/changed files are preserved.
for key,p in paths.items():
 if result[key]['present']:
  if key=='ready': os.rmdir(p)
  else: os.unlink(p)
subprocess.check_call(['sync'])
assert all(not os.path.lexists(p) for p in paths.values())
print('YI_READINESS '+json.dumps({'cleaned':True}))
